package com.bettertoppi.topuhud.modmenu;
import com.bettertoppi.topuhud.config.ConfigManager;import com.bettertoppi.topuhud.config.TopuHudConfig;import com.bettertoppi.topuhud.hud.HudManager;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.text.Text;
public final class TopuScreenEditor extends Screen{private final Screen parent;private final TopuHudConfig config;private HudManager.HudId dragging;private int dragOffsetX,dragOffsetY;public TopuScreenEditor(Screen parent){super(Text.literal("Topu HUD Editor"));this.parent=parent;this.config=ConfigManager.get();}@Override protected void init(){addDrawableChild(ButtonWidget.builder(Text.literal("Done"),button->closeEditor()).dimensions(width/2-50,height-30,100,20).build());}private void closeEditor(){dragging=null;ConfigManager.save();MinecraftClient.getInstance().setScreen(parent);}@Override public void close(){closeEditor();}@Override public boolean mouseClicked(double mouseX,double mouseY,int button){if(super.mouseClicked(mouseX,mouseY,button))return true;if(button!=0)return false;HudManager.HudId[] ids=HudManager.HudId.values();for(int i=ids.length-1;i>=0;i--){HudManager.HudId id=ids[i];if(!HudManager.isEnabledForEditor(id))continue;int[] p=HudManager.getPositionForEditor(config,id);int w=HudManager.getWidthForEditor(id),h=HudManager.getHeightForEditor(id);if(mouseX>=p[0]&&mouseX<=p[0]+w&&mouseY>=p[1]&&mouseY<=p[1]+h){dragging=id;dragOffsetX=(int)mouseX-p[0];dragOffsetY=(int)mouseY-p[1];return true;}}return false;}@Override public boolean mouseDragged(double mouseX,double mouseY,int button,double deltaX,double deltaY){if(button!=0||dragging==null)return super.mouseDragged(mouseX,mouseY,button,deltaX,deltaY);int w=HudManager.getWidthForEditor(dragging),h=HudManager.getHeightForEditor(dragging);int x=Math.max(0,Math.min(width-w,(int)mouseX-dragOffsetX));int y=Math.max(28,Math.min(height-30-h,(int)mouseY-dragOffsetY));HudManager.setPositionForEditor(config,dragging,x,y);return true;}@Override public boolean mouseReleased(double mouseX,double mouseY,int button){if(button==0&&dragging!=null){dragging=null;ConfigManager.save();return true;}return super.mouseReleased(mouseX,mouseY,button);}@Override public void render(DrawContext d,int mx,int my,float delta){d.fill(0,0,width,height,0xAA101010);d.fill(0,0,width,28,0xEE181818);d.drawText(textRenderer,Text.literal("TOPU HUD EDITOR"),10,9,0xFFFFFF,true);d.drawText(textRenderer,Text.literal("Drag HUD elements to move them"),10,38,0xAAAAAA,false);for(HudManager.HudId id:HudManager.HudId.values()){if(!HudManager.isEnabledForEditor(id))continue;int[] p=HudManager.getPositionForEditor(config,id);int w=HudManager.getWidthForEditor(id),h=HudManager.getHeightForEditor(id);boolean s=dragging==id;d.fill(p[0],p[1],p[0]+w,p[1]+h,s?0x6633AA77:0x55222222);d.fill(p[0],p[1],p[0]+w,p[1]+1,s?0xFF00FF88:0xFF777777);d.fill(p[0],p[1]+h-1,p[0]+w,p[1]+h,s?0xFF00FF88:0xFF777777);d.fill(p[0],p[1],p[0]+1,p[1]+h,s?0xFF00FF88:0xFF777777);d.fill(p[0]+w-1,p[1],p[0]+w,p[1]+h,s?0xFF00FF88:0xFF777777);d.drawText(textRenderer,display(id),p[0]+4,p[1]+4,s?0x00FF88:0xFFFFFF,true);}super.render(d,mx,my,delta);}private Text display(HudManager.HudId id){return switch(id){case ARMOR->Text.literal("Armor");case FPS->Text.literal("FPS");case PING->Text.literal("Ping");case TPS->Text.literal("TPS");case CPS->Text.literal("CPS");case COMBO->Text.literal("Combo");case TOTEM->Text.literal("Totems");case POTION->Text.literal("Potions");case EFFECTS->Text.literal("Effects");case GAPPLE->Text.literal("Gapples");case WARNING->Text.literal("Armor Warning");case ENEMY->Text.literal("Enemy HP");case COOLDOWN->Text.literal("Attack Cooldown");case BLOCK_OVERLAY->Text.literal("Block Overlay");case KEYSTROKES->Text.literal("Keystrokes");case MEMORY->Text.literal("Memory");};}}
